-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann Fernwartung im Anwendersupport technische Probleme remote lösen?', 2, '[{"text": "Ja", "correct": true, "because": "Ermöglicht direkten Zugriff"}, {"text": "Nein", "correct": false, "because": "Fernwartung ist dafür geeignet"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine Internetverbindung für Fernwartung im Anwendersupport erforderlich?', 2, '[{"text": "Ja", "correct": true, "because": "Verbindung zum Client nötig"}, {"text": "Nein", "correct": false, "because": "Internet ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Fernwartung nur für Softwareprobleme im Anwendersupport genutzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Hardware-Diagnose möglich"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Erfordert Fernwartung im Anwendersupport die Zustimmung des Nutzers?', 2, '[{"text": "Ja", "correct": true, "because": "Datenschutz und Sicherheit"}, {"text": "Nein", "correct": false, "because": "Zustimmung ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Fernwartung im Anwendersupport ohne spezielle Software möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Tools wie TeamViewer nötig"}, {"text": "Ja", "correct": false, "because": "Software wird benötigt"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird häufig für Fernwartung im Anwendersupport verwendet?', 2, '[{"text": "TeamViewer", "correct": true, "because": "Verbreitetes Fernwartungstool"}, {"text": "Notepad", "correct": false, "because": "Texteditor"}, {"text": "Telefon", "correct": false, "because": "Kein Fernwartungstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion ist bei Fernwartung im Anwendersupport am wichtigsten?', 3, '[{"text": "Bildschirmübertragung", "correct": true, "because": "Ermöglicht Problemansicht"}, {"text": "Dateiübertragung", "correct": false, "because": "Zusatzfunktion"}, {"text": "Chat", "correct": false, "because": "Kommunikation"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die größte Einschränkung der Fernwartung im Anwendersupport?', 2, '[{"text": "Physische Reparaturen", "correct": true, "because": "Nicht remote möglich"}, {"text": "Langsame Reaktion", "correct": false, "because": "Leistungsabhängig"}, {"text": "Softwarefehler", "correct": false, "because": "Behebbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt macht Fernwartung im Anwendersupport sicher?', 2, '[{"text": "Verschlüsselung", "correct": true, "because": "Schützt Datenübertragung"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Leistungsfaktor"}, {"text": "Telefonkontakt", "correct": false, "because": "Kein Sicherheitsmerkmal"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss vor der Fernwartung im Anwendersupport überprüft werden?', 2, '[{"text": "Internetverbindung", "correct": true, "because": "Grundvoraussetzung"}, {"text": "Hardwarestatus", "correct": false, "because": "Später relevant"}, {"text": "E-Mail-Adresse", "correct": false, "because": "Nicht notwendig"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Fernwartung im Anwendersupport?', 3, '[{"text": "Schnelle Problemlösung", "correct": true, "because": "Kein Vor-Ort-Besuch"}, {"text": "Kostenersparnis", "correct": true, "because": "Weniger Reiseaufwand"}, {"text": "Direkter Zugriff", "correct": true, "because": "Echtzeitsteuerung"}, {"text": "Hardwaretausch", "correct": false, "because": "Nicht möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bieten Fernwartungstools im Anwendersupport?', 4, '[{"text": "Bildschirmfreigabe", "correct": true, "because": "Problemvisualisierung"}, {"text": "Fernsteuerung", "correct": true, "because": "Direkte Eingriffe"}, {"text": "Dateiübertragung", "correct": true, "because": "Daten austauschen"}, {"text": "Telefonie", "correct": false, "because": "Separate Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei Fernwartung im Anwendersupport auftreten?', 3, '[{"text": "Verbindungsabbrüche", "correct": true, "because": "Netzwerkabhängig"}, {"text": "Sicherheitsrisiken", "correct": true, "because": "Datenexposition möglich"}, {"text": "Kompatibilitätsprobleme", "correct": true, "because": "Softwarekonflikte"}, {"text": "Langsame Festplatte", "correct": false, "because": "Hardwareproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Voraussetzungen sind für Fernwartung im Anwendersupport nötig?', 4, '[{"text": "Internetverbindung", "correct": true, "because": "Grundvoraussetzung"}, {"text": "Fernwartungssoftware", "correct": true, "because": "Tool erforderlich"}, {"text": "Nutzerzustimmung", "correct": true, "because": "Datenschutz"}, {"text": "Neuer Monitor", "correct": false, "because": "Hardwareunabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben können über Fernwartung im Anwendersupport erledigt werden?', 3, '[{"text": "Softwareinstallation", "correct": true, "because": "Remote möglich"}, {"text": "Fehlerdiagnose", "correct": true, "because": "Problemanalyse"}, {"text": "Treiberaktualisierung", "correct": true, "because": "Softwarebezogen"}, {"text": "Kabelreparatur", "correct": false, "because": "Physische Arbeit"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Fernwartung erfordert eine stabile Internetverbindung. b) Fernwartung kann Hardware defekte reparieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Internet ja, Hardware nicht möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) TeamViewer ist ein Beispiel für ein Fernwartungstool. b) Fernwartung funktioniert ohne Bildschirmfreigabe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "TeamViewer ja, Bildschirm essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fernwartung spart Zeit im Anwendersupport. b) Fernwartung ist unsicher und sollte vermieden werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zeitersparnis ja, Sicherheit machbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Fernwartung ermöglicht Softwareupdates. b) Fernwartung erfordert keinen Nutzerkontakt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Updates ja, Kontakt oft nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verschlüsselung schützt Daten bei Fernwartung. b) Fernwartung kann nur auf Windows-Systemen genutzt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung ja, plattformübergreifend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

